def frame_open(sec, pid=""):
    p = f" id=\"{pid}\"" if pid else ""
    return f"<div class=\"page\"{p}><div class=\"archival-frame\"><span class=\"filigree fl-tl\">{CORNER_SVG}</span><span class=\"filigree fl-tr\">{CORNER_SVG}</span><span class=\"filigree fl-bl\">{CORNER_SVG}</span><span class=\"filigree fl-br\">{CORNER_SVG}</span><div class=\"page-inner\"><div><div class=\"rhead\"><span>The Household Botanical Blueprint</span><span>{sec}</span></div>"
def frame_close(n): return f"</div><div class=\"rfoot\"><span>KALYANI BOTANICAL ARCHIVE &bull; KALYANIMA.IN</span><span>PAGE {n}</span></div></div></div></div>"
def plate(k, cls="plate-box"): return f"<div class=\"{cls}\">{PLATES[k]}</div>"
